        add("wiki.cyberneticenhancements.skills.title", "How Skills Work");
        add("wiki.cyberneticenhancements.skills.subtitle", "Passive talents that grow with your name.");
        add("wiki.cyberneticenhancements.skills.overview.1", "Skills are passive talents. You never activate them: every rank you buy quietly improves something you already do, from the price of a purchase to how far you can fall.");
        add("wiki.cyberneticenhancements.skills.overview.2", "There are 15 skills in four groups. Buy and review them in the Skills tab of the Neural Archive, where every skill shows its current bonus and what the next rank adds.");
        add("wiki.cyberneticenhancements.skills.overview.3", "Each skill has ranks from 0 to %s. A rank gives a tenth of the skill's top bonus, so every single rank is felt.");
        add("wiki.cyberneticenhancements.skills.group_row", "%s: %s");
        add("wiki.cyberneticenhancements.skills.group.social", "How contacts treat you: prices, pay and trust.");
        add("wiki.cyberneticenhancements.skills.group.cyberware", "How well your body takes chrome, and what ripperdocs charge you.");
        add("wiki.cyberneticenhancements.skills.group.technical", "Crafting, recycling and relic caches.");
        add("wiki.cyberneticenhancements.skills.group.survival", "Health, falls, healing and the damage the city deals.");
        add("wiki.cyberneticenhancements.skills.points.1", "Every [[system_street_cred|Street Cred]] level gives one skill point, and level 1 already gives one. A rank costs one point. Only the ranks you bought are stored, so your points can never drift away from your Street Cred.");
        add("wiki.cyberneticenhancements.skills.points.2", "There is no way to take a single point back. Reset skills in the Skills tab returns every bought rank at once, after a confirmation.");
        add("wiki.cyberneticenhancements.skills.points.3", "A reset costs %s eddies for every rank you had bought. Permanent lifepath ranks are kept.");
        add("wiki.cyberneticenhancements.skills.dialogue.1", "Fixers and ripperdocs offer extra answers when a skill is high enough. Locked answers show the rank they need.");
        add("wiki.cyberneticenhancements.skills.dialogue.2", "A passed check opens an extra line and a little commerce trust, within the daily limit. It never blocks a contract, and there are no dice rolls.");
        add("wiki.cyberneticenhancements.skills.notes.1", "Every price, cost or loss reduction is held at no more than half of the base value, so nothing ever becomes free.");
        add("wiki.cyberneticenhancements.skills.notes.2", "Servers can lower the rank limit, turn resetting off, or turn skills off entirely. Skills that are off keep their saved ranks and every dialogue check passes.");
        add("wiki.cyberneticenhancements.skills.top_rank", "At top rank: %s");
        add("wiki.cyberneticenhancements.skills.per_rank", "Each rank gives a tenth of the top bonus.");
        add("wiki.cyberneticenhancements.skills.dialogue_row", "%s: an extra answer from rank %s.");
        add("wiki.cyberneticenhancements.skills.origin_row", "%s: starts with %s permanent ranks.");
        add("skill.cyberneticenhancements.charisma.wiki", "Applies to the prices at every contact that sells, the pay of contracts, and how fast contacts warm to you.");
        add("skill.cyberneticenhancements.intimidation.wiki", "Applies to the pay of combat contracts: eliminations, cyberpsychos and breaches.");
        add("skill.cyberneticenhancements.streetwise.wiki", "Applies to the limit on trust you can earn from trading and skill dialogue in a day.");
        add("skill.cyberneticenhancements.deception.wiki", "Applies to the trust you lose when a contract is failed or abandoned.");
        add("skill.cyberneticenhancements.chrome_tolerance.wiki", "Applies to your total implant capacity and to the instability that cyberstrain builds up.");
        add("skill.cyberneticenhancements.maintenance.wiki", "Applies to how fast installed cyberware wears and to the price of servicing it at NPCs.");
        add("skill.cyberneticenhancements.neural_resistance.wiki", "Applies to how fast cyberpsychosis instability builds up.");
        add("skill.cyberneticenhancements.ripperdoc_rapport.wiki", "Applies to everything a ripperdoc sells or does for you.");
        add("skill.cyberneticenhancements.fabrication.wiki", "Applies to the speed of fabricators while you are online, and gives a chance to save one unit of the largest multi-unit ingredient.");
        add("skill.cyberneticenhancements.scavenging.wiki", "Applies to relic caches: a chance to roll the loot twice and keep the better result.");
        add("skill.cyberneticenhancements.engineering.wiki", "Applies to the output of recycler stations you started, while you are online and the output has room.");
        add("skill.cyberneticenhancements.resilience.wiki", "Applies to your maximum health.");
        add("skill.cyberneticenhancements.athletics.wiki", "Applies to the damage you take from falling.");
        add("skill.cyberneticenhancements.street_medicine.wiki", "Applies to instant healing from consumables such as MaxDoc and Bounce Back.");
        add("skill.cyberneticenhancements.evasion.wiki", "Applies to the damage dealt to you by city NPCs and cyberpsychos.");
        add("wiki.cyberneticenhancements.streetcred.title", "Street Cred");
        add("wiki.cyberneticenhancements.streetcred.subtitle", "How well the city knows your name.");
        add("wiki.cyberneticenhancements.streetcred.overview.1", "Street Cred is a measure of how well known you are in the city. It is a single level from 1 to %s that only ever goes up, and it is never lost.");
        add("wiki.cyberneticenhancements.streetcred.overview.2", "Everyone starts at level 1 as a nobody. As your Street Cred grows, your level and the rank that goes with it grow too.");
        add("wiki.cyberneticenhancements.streetcred.overview.3", "Street Cred is yours alone. It stays with you through death, and other players cannot raise or lower it.");
        add("wiki.cyberneticenhancements.streetcred.rank_row", "Level %s: %s");
        add("wiki.cyberneticenhancements.streetcred.rank_top", "Level %s: %s");
        add("wiki.cyberneticenhancements.streetcred.progress.1", "Street Cred is counted in points. The first level costs %s points and every level after it costs %s more than the one before. Reaching level %s takes %s points in total.");
        add("wiki.cyberneticenhancements.streetcred.progress.2", "A [[origin_street_kid|Street Kid]] earns %s%% more Street Cred from everything, because the street remembers its own. The other lifepaths earn it at the normal rate.");
        add("wiki.cyberneticenhancements.streetcred.display.1", "Whenever your Street Cred changes, a small panel opens in the same place as calls and contracts. It shows the change, your level and rank, and how far you are from the next level.");
        add("wiki.cyberneticenhancements.streetcred.display.2", "The panel appears even when other HUD parts are hidden. If a call or the contact list is open, it waits until they close. A level-up stays on screen longer, and a new rank is named.");
        add("wiki.cyberneticenhancements.section.ranks", "Ranks");
        add("wiki.cyberneticenhancements.section.earning", "Earning it");
        add("wiki.cyberneticenhancements.section.worth", "What it is worth");
        add("wiki.cyberneticenhancements.streetcred.effects.intro", "A name only ever helps. Every bonus grows evenly with each level, from nothing at level 1 to its maximum at the top, so every level is felt a little.");
        add("wiki.cyberneticenhancements.streetcred.effects.pay", "Contract pay: up to +%s%% on the money of every contract, on top of any lifepath bonus.");
        add("wiki.cyberneticenhancements.streetcred.effects.trust", "Trust: contacts warm to you up to %s%% faster, so discounts and better work arrive sooner.");
        add("wiki.cyberneticenhancements.streetcred.effects.prices", "Prices: up to %s%% off at every contact that sells, stacking with trust discounts and the lifepath.");
        add("wiki.cyberneticenhancements.streetcred.effects.tiers", "Dangerous work: from level %s issuers offer tier 2 contracts and from level %s tier 3, even before they trust you enough on their own.");
        add("wiki.cyberneticenhancements.streetcred.effects.note", "Nothing is ever taken away: a low name simply gets none of this. Every level also gives one skill point to spend on [[skills_overview|Skills]].");
        add("screen.cyberneticenhancements.archive.reputation.perks", "WHAT IT IS WORTH");
        add("screen.cyberneticenhancements.archive.reputation.perk_pay", "Contract pay  +%s%%");
        add("screen.cyberneticenhancements.archive.reputation.perk_trust", "Trust gain  +%s%%");
        add("screen.cyberneticenhancements.archive.reputation.perk_prices", "Prices  -%s%%");
        add("screen.cyberneticenhancements.archive.reputation.perk_tier", "Contracts up to tier %s");
        add("wiki.cyberneticenhancements.streetcred.earning.intro", "Street Cred is earned by doing the work of the city and coming out of it alive. Each of these pays once for each thing you do:");
        add("wiki.cyberneticenhancements.streetcred.earning.contract", "Finishing a contract: %s to %s points, more for harder contract types and higher tiers. Contracts are the steady way up.");
        add("wiki.cyberneticenhancements.streetcred.earning.cyberpsycho", "Putting down a cyberpsycho: %s to %s points, more for the higher tiers. It counts whether or not a contract asked for it.");
        add("wiki.cyberneticenhancements.streetcred.earning.max_tac", "Defeating a full MaxTac squad that was sent after you: %s points.");
        add("wiki.cyberneticenhancements.streetcred.earning.cache", "Hacking open a relic cache for the first time: %s to %s points, more for the rarer caches.");
        add("wiki.cyberneticenhancements.streetcred.earning.chromium", "Discovering a large chromium deposit: %s points.");
        add("wiki.cyberneticenhancements.streetcred.earning.tarot", "Archiving a tarot card: %s points.");
        add("wiki.cyberneticenhancements.streetcred.earning.schematic", "Learning a new schematic: %s points.");
        add("wiki.cyberneticenhancements.streetcred.earning.note", "Nothing pays for time spent, and nothing can be repeated: a cache, a card, a schematic or a deposit only counts the first time. Street Cred is never lost, not even by dying.");
        add("wiki.cyberneticenhancements.section.progress", "Progress");
