        add("wiki.cyberneticenhancements.fasttravel.overview.1", "A Fast Travel Terminal is an enchanting table that projects a hologram instead of holding a book. Every Night City has one where the village bell would hang, and you can craft more from an ender pearl, redstone, an enchanting table and iron.");
        add("wiki.cyberneticenhancements.fasttravel.overview.2", "Each terminal is a node. Nodes you have found are marked on the map, in the Archive and on the travel screen.");
        add("wiki.cyberneticenhancements.fasttravel.use.1", "Right-click a terminal once to activate it. This adds it to your network, and it stays there for good. A terminal you place yourself is already active for you.");
        add("wiki.cyberneticenhancements.fasttravel.use.2", "Right-click an active terminal to open the map showing every node you have activated, then click one to travel there. You have to stand next to the terminal you leave from.");
        add("wiki.cyberneticenhancements.fasttravel.use.3", "A trip costs %s eurodollars by default, taken from your account when you click. If the destination is gone by the time you arrive, you are refunded.");
        add("wiki.cyberneticenhancements.fasttravel.notes.1", "You dissolve into a hologram while the screen washes cyan, then materialize at the destination. Other players see it happen.");
        add("wiki.cyberneticenhancements.fasttravel.notes.2", "Breaking a terminal removes the node for everyone. Nodes work across dimensions.");
        add("wiki.cyberneticenhancements.fasttravel.notes.3", "Servers can change the price or turn fast travel off completely.");
        add("wiki.cyberneticenhancements.links.title", "Linking to Articles");
        add("wiki.cyberneticenhancements.links.subtitle", "Share an article in chat, or link one from another.");
        add("wiki.cyberneticenhancements.links.overview.1", "Put a # in front of the name of an article or category and it becomes a blue, underlined link once the message is sent. Clicking it opens the Neural Archive on that article.");
        add("wiki.cyberneticenhancements.links.overview.2", "Links inside articles work the same way. Clicking one opens the article, switches to the right tab and scrolls to the section.");
        add("wiki.cyberneticenhancements.links.overview.3", "Other players only see the link if they have the mod too. Without it they just see the text you typed.");
        add("wiki.cyberneticenhancements.section.chat", "In chat");
        add("wiki.cyberneticenhancements.links.chat.1", "#Arms opens the Arms category, and #Gorilla_Arms opens that article. Names are not case sensitive, and spaces are written as underscores.");
        add("wiki.cyberneticenhancements.links.chat.2", "Add a / and a section to link to one part of an article. #Corpo/Players opens the player list of the Corpo lifepath.");
        add("wiki.cyberneticenhancements.links.chat.3", "A # word that matches no article stays as plain text, so ordinary hashtags are not affected.");
        add("wiki.cyberneticenhancements.section.preview", "Preview");
        add("wiki.cyberneticenhancements.links.preview.1", "While you type a # in the chat box, a list above it shows the articles and categories that match. If nothing matches, it says so.");
        add("wiki.cyberneticenhancements.links.preview.2", "Press Tab or click an entry to complete it. Up and Down choose between entries. After a / the list shows the sections of that article.");
        add("wiki.cyberneticenhancements.section.commands", "Command");
        add("wiki.cyberneticenhancements.links.commands.1", "/cewiki <name> opens an article directly, for example /cewiki corpo#players. Names complete with Tab.");
        add("wiki.cyberneticenhancements.links.commands.2", "This is how a link looks inside an article, [[origin_corpo#players|Corpo players]], and this one goes to a whole article, [[system_controls|Controls & Archive]].");
