        add("wiki.cyberneticenhancements.npc.role.maxtec", "A resident MaxTec officer patrols Night City, removes reachable hostile mobs inside its boundaries and protects local residents. Talk to an officer to add them as a contact. Assaulting one provokes an immediate armed response.");
        add("screen.cyberneticenhancements.npc.dialogue.maxtec.line.root", "MaxTec. City patrol. Keep your hands where I can see them. What do you need?");
        add("screen.cyberneticenhancements.npc.dialogue.maxtec.line.about", "I keep this district clear of hostiles. Reach me by phone once we've met.");
        add("screen.cyberneticenhancements.npc.dialogue.maxtec.line.work", "Creepers, infected, cyberpsychos. If they threaten this district and I can reach them, I deal with them.");
        add("screen.cyberneticenhancements.npc.dialogue.maxtec.line.advice", "Stay clear of hostile mobs and give us room to work. A uniform's not target practice.");
