        add("screen.cyberneticenhancements.npc.dialogue.med_tech.line.root", "MedTec. Medical services and Trauma Team coverage. Open Services to buy a single rescue dispatch. Keep your coverage active before you head into danger.");
        add("screen.cyberneticenhancements.npc.dialogue.med_tech.line.about", "I'm a MedTec responder. Field medicine, and emergency rescue coverage for people who plan ahead.");
        add("screen.cyberneticenhancements.npc.dialogue.med_tech.line.work", "Open Services for one Trauma Team dispatch or clinical stabilization. Coverage lasts until you use it.");
        add("screen.cyberneticenhancements.npc.dialogue.med_tech.line.advice", "Coverage isn't invincibility. Responders need a reachable approach and three seconds beside you. Rescue can fail in dangerous terrain.");
        add("screen.cyberneticenhancements.npc.dialogue.med_tech.line.trust", "Trust grows when we talk and you use my services. Coverage itself doesn't need a trust rank.");
        add("screen.cyberneticenhancements.npc.dialogue.med_tech.line.terms", "One policy covers one dispatch. A successful rescue keeps your inventory and doesn't count as a death. Respawn, and the rescue is abandoned.");
