        add("screen.cyberneticenhancements.npc.dialogue.fixer.player.agreed", "That sounds fair.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.root", "Need patching up or medical supplies? Take a look at the services and stock. If your chrome's worrying you, let's talk first.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.about", "I keep people running when their cyberware starts wearing them down. Also sell medical supplies and a few basic implants.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.work", "Clinic care restores health and eases cyberstrain. Detox clears harmful effects and neural pressure. For worn implants, use a Repair Station.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.advice", "More chrome, more strain, kid. Watch your integrity and cyberstrain readings, and fix damaged implants before you bet your life on them.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.trust", "Keep coming back, pay for treatment, show some respect, and you'll earn my trust. Detox opens up once I know you better.");
        add("screen.cyberneticenhancements.npc.dialogue.ripperdoc.line.terms", "Detox needs more trust and runs once per world day. It clears active neural doses too. Treatment prices are on each card.");
