        add("screen.cyberneticenhancements.npc.dialogue.techie.line.root", "Need parts, a quick tune-up or a gig? Pick one. We can talk shop after.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.about", "I mess with cyberware and workshop supplies. Sell practical kit, and I've got gigs that'll help pay for your next build.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.work", "Open Contracts for my jobs. Repairs, upgrades and recycling happen at stations. For services I do mining speed or protection for hazardous work.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.advice", "Learn the schematic before you spend on fabrication materials. Keep the good salvage, and repair a solid implant before sinking more into upgrading it.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.trust", "Finish my gigs, buy supplies, keep your word. More trust gets you better prices and hazard prep.");
        add("screen.cyberneticenhancements.npc.dialogue.techie.line.terms", "Mining calibration gives Haste II. Hazard prep gives fire resistance and damage resistance. Both last five minutes. Neither upgrades an implant.");
