        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.root", "Need gear, a gig, or a relic cache location? I've got it. Also recon support and a stealth protocol.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.about", "Data and neural hardware. I sell memory and RAM gear, run gigs, and keep a few cache locations on file.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.work", "Read the objective before you accept. Delivery means dropping the package in the marked Iron Quest Crate. Extraction means pulling the shard from one and bringing it back.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.advice", "Before a breach, look for token sequences that overlap. Your first pick starts the clock. Plan first, commit second.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.trust", "Finish my gigs, stay reliable. Trust opens better prices and the stealth protocol. Browsing's free.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.line.terms", "Recon support gives night vision and speed for eight minutes. Stealth gives invisibility and speed for three. Armor stays visible.");
        add("screen.cyberneticenhancements.npc.dialogue.netrunner.player.shop", "Let me see what you\u0027re selling.");
