        add("screen.cyberneticenhancements.npc.dialogue.merc.line.root", "Looking for work or kit? I've got gigs, combat gear and a bit of field support. Say what you need.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.about", "I take dangerous work and sell kit to people who do the same. Read the job, bring what you need, come back alive.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.work", "Open Contracts for the job list. Check the objective, not every gig is a kill order. Come back when it's done and I'll pay up.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.advice", "Check your health, your implants and your supplies before you head out. Use cover. A decent plan costs less than replacing your gear.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.trust", "Finish your gigs, buy supplies. More trust opens combat prep and better prices. Quit on me and I trust you less.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.line.terms", "Field recovery gives regeneration and absorption. Combat prep gives strength and resistance for three minutes. Prep takes more trust.");
        add("screen.cyberneticenhancements.npc.dialogue.merc.player.shop", "Let me see what you\u0027re selling.");
