        add("screen.cyberneticenhancements.npc.line.fixer.identity", "We go back far enough you can rename me, restyle me, whatever. Say what you want changed.");
        add("screen.cyberneticenhancements.npc.line.ripperdoc.identity", "You've been in my chair enough times. Want a new name on the door, a new look? Tell me.");
        add("screen.cyberneticenhancements.npc.line.techie.identity", "Hey, we've worked together enough. Wanna swap my name, my look? Go for it.");
        add("screen.cyberneticenhancements.npc.line.netrunner.identity", "Fine, you've earned root access. Change my name, my face. Whatever you want.");
        add("screen.cyberneticenhancements.npc.line.merc.identity", "We've bled together, more or less. Change my name, my look, whatever. Say it.");
        add("screen.cyberneticenhancements.npc.line.fixer.greeting", "Supplies or implant trouble? I can sort both. And I know where a few relic caches are hiding.");
        add("screen.cyberneticenhancements.npc.line.fixer.services", "Strain buffers buy you some breathing room. Neural reset clears psychosis and active doses. Neither fixes busted chrome, so don't ask.");
        add("screen.cyberneticenhancements.npc.line.fixer.shop", "Everything's priced on the card. Hit Buy when you're ready.");
        add("screen.cyberneticenhancements.npc.line.fixer.contracts", "Fixers don't run a board, choom. Supplies, services, that's my lane.");
        add("screen.cyberneticenhancements.npc.choice.fixer.service_stabilize", "Stabilizing dose [%s €$]");
        add("screen.cyberneticenhancements.npc.choice.fixer.service_purge", "Purge harmful effects [%s €$]");
        add("screen.cyberneticenhancements.npc.response.fixer.intro", "I move hardware and I keep chromed-up folks from cooking their own heads. Ask what you need, I'll quote you the price. Straight up.");
        add("screen.cyberneticenhancements.npc.response.fixer.cache_intel", "Got a cache near you. Marked it on your compass, coordinates are in chat too. Follow the marker, and don't thank me, thank the eddies.");
        add("screen.cyberneticenhancements.npc.response.fixer.stabilize_ok", "Buffer's in. Your effective cyberstrain drops for two minutes. Don't waste it.");
