        add("wiki.cyberneticenhancements.world_encounter.shipping_container.rules.spacing", "Spacing");
        add("wiki.cyberneticenhancements.world_encounter.shipping_container.rules.spacing.value", "One attempt per 20 chunks, never closer than 6 chunks apart");
        add("wiki.cyberneticenhancements.world_encounter.shipping_container.rules.ground", "Placement");
