        add("wiki.cyberneticenhancements.world_encounter.shipping_container.condition.note", "The wreck itself is one of ten different containers, turned at random. How badly it is broken is decided once when it generates.");
        add("wiki.cyberneticenhancements.world_encounter.shipping_container.condition.heading", "Condition");
