        add("quest.cyberneticenhancements.title.fixer.cyberpsycho", "Cyberpsycho Sighting");
        add("quest.cyberneticenhancements.title.ripperdoc.cyberpsycho", "Cyberpsycho Sighting");
        add("quest.cyberneticenhancements.title.techie.cyberpsycho", "Cyberpsycho Sighting");
        add("quest.cyberneticenhancements.title.netrunner.cyberpsycho", "Cyberpsycho Sighting");
        add("quest.cyberneticenhancements.title.merc.cyberpsycho", "Cyberpsycho Sighting");
        add("quest.cyberneticenhancements.objective.cyberpsycho", "Search within 48 blocks of the sighting marker for %s. Kill the cyberpsycho, collect their information shard, and hand it to the issuer in person. Extreme danger: bring armor and supplies.");
        add("quest.cyberneticenhancements.objective.cyberpsycho.shard", "%s is neutralized. Collect the marked dossier shard and hand it to the issuer in person.");
        add("quest.cyberneticenhancements.objective.cyberpsycho.offer", "Search the approximate sighting area, kill the named cyberpsycho and return their information shard in person. Extreme danger; highest contract payouts.");
        add("quest.cyberneticenhancements.marker.cyberpsycho.area", "Sighting area: %s");
        add("quest.cyberneticenhancements.marker.cyberpsycho.shard", "Dossier: %s");
        add("message.cyberneticenhancements.quest.cyberpsycho.nearby", "You have reached %s's reported sighting area. Search nearby and prepare for heavy cyberware attacks.");
        add("message.cyberneticenhancements.quest.cyberpsycho.killed", "%s neutralized. Collect the information shard from their body before returning to the quest giver.");
        add("message.cyberneticenhancements.quest.replacement_available", "Courier Package missing. Call %s to request another; completion rewards will be reduced to 50%%.");
        add("message.cyberneticenhancements.quest.item_lost_failed", "%s failed: the return item was lost. %s lost %s trust in you.");
        add("message.cyberneticenhancements.quest.urgent_expired", "%s failed. The deadline passed.");
        add("quest.cyberneticenhancements.objective.item_missing", "Contact %s about the missing return item.");
        add("quest.cyberneticenhancements.objective.replacement", "Call %s to request a replacement package.");
        add("quest.cyberneticenhancements.reward.replacement_penalty", " · 50% rewards after replacement");
        add("screen.cyberneticenhancements.call.incoming.item_lost", "You lost the item for %s? That was the whole job. Unless you've still got it somewhere, this contract's finished.");
        add("screen.cyberneticenhancements.call.incoming.cache_failed", "You botched %s and lost the cache? That was the whole job. No cache, no pay. You cost me time and trust.");
        add("screen.cyberneticenhancements.call.incoming.cache_failed_acknowledged", "Next time, prepare before you touch a secured cache. Don't waste another shot.");
        add("screen.cyberneticenhancements.call.choice.cache_failed_acknowledge", "I understand. I messed up.");
        add("screen.cyberneticenhancements.call.incoming.item_still_owned", "Then keep it safe and bring it back. The contract stays open. I won't ask again unless you find it and lose it a second time.");
        add("screen.cyberneticenhancements.call.incoming.item_lost_ended", "We're done. No item, no pay. Next time, take better care of what you're carrying.");
        add("screen.cyberneticenhancements.call.choice.still_have_item", "No, wait, I actually still have it.");
        add("screen.cyberneticenhancements.call.choice.lost_item", "It's gone. I lost it.");
        add("screen.cyberneticenhancements.call.choice.replacement", "I need another package — 50% rewards.");
        add("screen.cyberneticenhancements.call.quest.replacement_issued", "Another package's on you. Rewards are now 50%: money, trust, XP, supplies and bonus chances. Earlier copies are dead.");
        add("screen.cyberneticenhancements.call.quest.replacement_unavailable", "You've already got the package, or it already reached its destination. Nothing to replace.");
        add("message.cyberneticenhancements.quest.cyberpsycho_ready", "Cyberpsycho dossier secured. Hand it over to %s in person to complete the contract.");
        add("quest.cyberneticenhancements.type.salvage", "Salvage");
        add("quest.cyberneticenhancements.title.salvage", "Lost Cargo");
        add("quest.cyberneticenhancements.title.fixer.salvage", "Cargo Retrieval");
        add("quest.cyberneticenhancements.title.ripperdoc.salvage", "Lost Shipment");
        add("quest.cyberneticenhancements.title.techie.salvage", "Wreck Salvage");
        add("quest.cyberneticenhancements.title.netrunner.salvage", "Lost Drive");
        add("quest.cyberneticenhancements.title.merc.salvage", "Overboard Cargo");
        add("quest.cyberneticenhancements.target.cargo", "lost cargo");
        add("quest.cyberneticenhancements.objective.salvage", "A shipping container went down at sea or washed ashore, and one of its crates holds sealed cargo. Find the container and the crate with a golden \"!\" floating over it, take the cargo, and bring it back in person. A sealed container has to be broken open first. Anything else you find inside is yours to keep.");
        add("quest.cyberneticenhancements.cancelled.cargo_lost", "The cargo is gone again. It was lost long before it reached you, so you are not blamed.");
        add("message.cyberneticenhancements.quest.salvage_ready", "Cargo recovered. Bring it to %s in person.");
        add("message.cyberneticenhancements.quest.salvage_found", "The sealed cargo you found belongs to %s. Bring it to them in person.");
        add("item.cyberneticenhancements.lost_cargo.owned", "Sealed Cargo (%s)");
        add("tooltip.cyberneticenhancements.lost_cargo.return", "Belongs to %s. Hand it over in person.");
        add("tooltip.cyberneticenhancements.lost_cargo.lost", "Lost once already: if it goes missing again, nobody is blamed.");
        add("screen.cyberneticenhancements.call.quest.help.salvage.0", "A container went down at sea or washed up on a beach, and one of its crates holds my cargo. Look for the golden \"!\" over the crate, take the cargo and bring it to me. Keep whatever else you find.");
        add("screen.cyberneticenhancements.call.quest.help.salvage.1", "Search the coast and the sea floor for the container. If it's sealed, you'll have to break through the hull. The sealed cargo is in a crate inside. Everything else in there is yours, I only want that back.");
        add("screen.cyberneticenhancements.call.quest.help.salvage.2", "It's in a crate inside the lost container. Bring me the cargo in person. Lose it again and nobody'll blame you.");
        add("quest.cyberneticenhancements.type.locate", "Patient Search");
        add("quest.cyberneticenhancements.title.locate", "Patient Search");
        add("quest.cyberneticenhancements.title.med_tech.locate", "Missing Patient");
        add("quest.cyberneticenhancements.target.patient", "missing patient");
        add("quest.cyberneticenhancements.objective.locate", "Find the patient slumped against a wall inside the marked area; the coordinates are only roughly right. Revive them with the Emergency Revive Injector, then use the Signal Beacon right beside them.");
        add("quest.cyberneticenhancements.objective.locate.beacon", "The patient is stable. Stand next to them and use the Signal Beacon anywhere to log your position, then bring the beacon back to the MedTec team.");
        add("message.cyberneticenhancements.quest.locate_ready", "Position logged. Bring the Signal Beacon back to %s in person; they will check it against where the patient lies.");
        add("message.cyberneticenhancements.quest.locate.revived", "The patient gasps awake. Now stand beside them and use the Signal Beacon.");
        add("message.cyberneticenhancements.quest.locate.needs_injector", "This patient needs the Emergency Revive Injector.");
        add("message.cyberneticenhancements.quest.locate.needs_beacon", "Use the Signal Beacon to log your position.");
        add("message.cyberneticenhancements.quest.locate.already_logged", "This beacon has already logged a position.");
        add("message.cyberneticenhancements.quest.locate.false_report", "%s: the beacon was nowhere near a living patient. No pay, and they are coming for you.");
        add("message.cyberneticenhancements.quest.locate.coverage", "MedTec has added a year of Trauma Team coverage to your file.");
        add("message.cyberneticenhancements.quest.locate_failed", "%s failed: a quest item was lost and the patient is beyond saving. %s will want a word.");
        add("quest.cyberneticenhancements.reward.coverage", "free MedTec coverage");
        add("tooltip.cyberneticenhancements.revive_injector.use", "Right-click the missing patient to revive them.");
        add("tooltip.cyberneticenhancements.signal_beacon.use", "Right-click anywhere to log your position. It must be within 10 blocks of the patient.");
        add("tooltip.cyberneticenhancements.signal_beacon.set", "Position logged: %s, %s, %s");
        add("tooltip.cyberneticenhancements.signal_beacon.return", "Bring it back to %s.");
        add("tooltip.cyberneticenhancements.quest_item.lose", "Quest item: losing it fails the contract.");
        add("screen.cyberneticenhancements.call.incoming.patient_lost", "You lost the gear for %s. The patient's gone, and so is the contract. We trusted you with a life.");
        add("screen.cyberneticenhancements.call.incoming.patient_lost_acknowledged", "Be more careful next time. This line closes now.");
        add("entity.cyberneticenhancements.world_encounter_npc", "MedTec");
        add("entity.cyberneticenhancements.world_encounter.patient", "Patient");
        add("screen.cyberneticenhancements.npc.dialogue.world_encounter.line.root", "MedTec Field Recovery. This site's under corporate control. Keep your distance from our equipment and follow my instructions. We've got a recovery situation, and you might be useful.");
        add("screen.cyberneticenhancements.npc.dialogue.world_encounter.line.about", "MedTec. This is a managed site and everything on it is company property. You're here on our tolerance, so let's keep it orderly.");
        add("screen.cyberneticenhancements.npc.dialogue.world_encounter.line.work", "A patient of ours went missing and our tracking's down. Find them, revive them with this injector, log your position beside them with the beacon and bring it back to me. You've got twenty minutes. Lie to me and you'll regret it. Pay's good.");
        add("screen.cyberneticenhancements.npc.dialogue.world_encounter.player.contracts", "What is it you want from me?");
        add("screen.cyberneticenhancements.npc.dialogue.world_encounter.player.talk", "Who runs this site?");
        add("screen.cyberneticenhancements.npc.dialogue.world_encounter.player.work", "Where is this patient?");
        add("screen.cyberneticenhancements.npc.dialogue.world_encounter.player.goodbye", "I'll leave you to it.");
        add("screen.cyberneticenhancements.npc.dialogue.world_encounter.player.back", "Back to the assignment.");
        add("item.cyberneticenhancements.cyberpsycho_dossier", "Cyberpsycho Dossier: %s");
        add("tooltip.cyberneticenhancements.cyberpsycho.subject", "Subject: %s / Status: neutralized");
        add("tooltip.cyberneticenhancements.cyberpsycho.cyberware", "Recovered implant records: %s");
        add("tooltip.cyberneticenhancements.cyberpsycho.return", "Hand to %s in person to receive payment.");
        add("entity.cyberneticenhancements.max_tac", "MaxTec");
        add("entity.cyberneticenhancements.encounter_body", "Body");
        add("entity.cyberneticenhancements.gang_member", "Gang Member");
        add("gamerule.cyberneticStreetEncounters", "Random street encounters");
        add("gamerule.cyberneticStreetEncounters.description", "Lets wandering ripperdocs and gang shakedowns turn up now and then for players walking outdoors in the Overworld.");
        add("message.cyberneticenhancements.encounter.ripperdoc", "A street ripperdoc is heading your way from about %s blocks off. They carry real chrome and will wait %s minutes if they cannot reach you, or if you ignore them.");
        add("message.cyberneticenhancements.encounter.shakedown.prey", "Four of them fan out around you and one grins. \"Look at this fresh meat. Toll's %s eurodollars, nobody. You've got %s seconds.\"");
        add("message.cyberneticenhancements.encounter.shakedown.street", "A gang closes in. \"Toll's %s eurodollars, choom. You've got %s seconds.\"");
        add("message.cyberneticenhancements.encounter.shakedown.known", "Two of them step into your path, hands where you can see them. \"We've heard of you. It's %s eurodollars, nothing personal. Take %s seconds.\"");
        add("message.cyberneticenhancements.encounter.shakedown.feared", "The boss can't quite meet your eyes. \"It's you. Look, we gotta ask. %s eurodollars, or just say no. Take your time, %s seconds.\"");
        add("message.cyberneticenhancements.encounter.shakedown.name", "[Say your name]");
        add("message.cyberneticenhancements.encounter.shakedown.nobody", "You say a name. They've never heard it, and they laugh.");
        add("message.cyberneticenhancements.encounter.shakedown.recognised", "The boss goes pale. \"You. Forget it. We were never here.\"");
        add("message.cyberneticenhancements.encounter.shakedown.unknown", "They look at each other. \"Never heard of you.\" Then they come for you.");
        add("message.cyberneticenhancements.encounter.tribute", "The gang steps aside and the boss holds out a chip. \"Heard you were back in the district. This is for you: %s eurodollars. Nobody wants trouble with you. You've got %s seconds.\"");
        add("message.cyberneticenhancements.encounter.tribute.take", "Take the %s eurodollars.");
        add("message.cyberneticenhancements.encounter.tribute.decline", "Keep it. I do not need your money.");
        add("message.cyberneticenhancements.encounter.tribute.taken", "You take the chip. %s eurodollars land in your account. The gang nods and fades back into the street.");
        add("message.cyberneticenhancements.encounter.tribute.declined", "You push the chip back. The boss nods slowly. Word's gonna get around.");
        add("message.cyberneticenhancements.encounter.tribute.timeout", "You say nothing. The gang takes the hint and leaves.");
        add("wiki.cyberneticenhancements.section.shakedown_cred", "How your name changes it");
        add("wiki.cyberneticenhancements.encounter.shakedown.cred.1", "Nobody (levels 1-19): easy money. Four of them come, with a toll of %s%% of your balance (%s to %s), only %s seconds to answer, and your chrome impresses them half as much. A shakedown is the street's favourite thing to do to a nobody, so they happen more often.");
        add("wiki.cyberneticenhancements.encounter.shakedown.cred.2", "Street names (levels 20-49): the plain version, three of them, %s%% of your balance (%s to %s) and %s seconds. From level 20 you can also say your name instead of paying, and the higher your level, the likelier they know it.");
        add("wiki.cyberneticenhancements.encounter.shakedown.cred.3", "Known names (levels 50-79): only two come, the toll is %s%% (%s to %s) and you get %s seconds. They are better armed, but reputation adds %s%% to the chance that a refusal is taken seriously.");
        add("wiki.cyberneticenhancements.encounter.shakedown.cred.4", "Feared names (levels 80-100): two of them, much tougher, with a toll of only %s%% (%s to %s) and %s seconds to decide. Most of the time they do not come to take at all: they come with tribute, %s to %s eurodollars. Take it for the money, or turn it down for the respect.");
        add("wiki.cyberneticenhancements.encounter.shakedown.cred.5", "Saying your name chance: %s%% at level 20, %s%% at level 50 and %s%% at level 100. Backing a gang down, or turning down their tribute, earns %s Street Cred. Failing makes them attack.");
        add("dialogue.cyberneticenhancements.leave", "That's all.");
        add("dialogue.cyberneticenhancements.leader.refuses", "You've done enough here. Nothing left to say to you.");
        add("dialogue.cyberneticenhancements.reason.unfinished", "The job is not finished yet.");
        add("dialogue.cyberneticenhancements.requires_street_cred", "Requires Street Cred %s");
        add("dialogue.cyberneticenhancements.shakedown.name", "Do you know who I am? (%s%% they do)");
        add("dialogue.cyberneticenhancements.shakedown.name.locked", "Do you know who I am?");
        add("dialogue.cyberneticenhancements.shakedown.stare", "Say nothing. Just look at them.");
        add("message.cyberneticenhancements.encounter.shakedown.stare", "You don't say a word. The boss meets your eyes, swallows, and waves the others back. \"Our mistake.\"");
        add("dialogue.cyberneticenhancements.hand_in", "Hand in quest");
