        add("wiki.cyberneticenhancements.quest_guide.schematic", "Missing schematic (up to design tier %s): %s");
        add("wiki.cyberneticenhancements.quest_guide.per_design", "%s eligible unlearned designs; %s per design. Pool updates as you learn schematics.");
        add("wiki.cyberneticenhancements.quest_guide.fallback", "Bonus part: %s chance of 1 x %s (all eligible schematics learned).");
        add("wiki.cyberneticenhancements.quest_guide.no_bonus", "No extra discovery/core: %s");
        add("wiki.cyberneticenhancements.quest_guide.objective.delivery", "Carry the Courier Package to the marked Iron Quest Crate. Lost packages are not restored automatically: call the issuer for another. Replacements reduce completion rewards and bonus chances to 50%; whole-number rewards round down. Earlier copies become invalid.");
        add("wiki.cyberneticenhancements.quest_guide.objective.extraction", "Recover the extraction shard, then return it to the issuer. If it goes missing for 10 seconds, the issuer calls angrily. Admit the loss, decline or miss the call and the quest fails. Say you still have it to keep the quest open while it is in external storage. Lost shards are never replaced.");
        add("wiki.cyberneticenhancements.quest_guide.objective.investigation", "Take three separated bearings by crouching with empty hands in the survey area. Triangulate the signal, then reach its source.");
        add("wiki.cyberneticenhancements.quest_guide.objective.breach", "Reach the marked cache and complete its breach puzzle. Failure ends the contract and triggers an angry call from the issuer; prepare before starting.");
        add("wiki.cyberneticenhancements.quest_guide.objective.elimination", "Travel to the marked encounter and defeat the assigned hostile targets. Required kills increase with tier.");
        add("wiki.cyberneticenhancements.quest_guide.objective.recovery", "Gather the requested material and quantity from your inventory, then hand it over. The payout includes material compensation.");
        add("wiki.cyberneticenhancements.quest_guide.objective.cyberpsycho", "Defeat the cyberpsycho, loot the dossier and return it to the issuer. Losing it for 10 seconds triggers an angry call: confirm you still own it in external storage, or the quest fails when you admit the loss, decline or miss the call. Dossiers are never replaced.");
        add("wiki.cyberneticenhancements.quest_guide.objective.chromium_survey", "The Techie's investigation variant: take three separated readings around the geological prospect by crouching with empty hands. Completion reveals a chromium deposit and pays four Chromium Alloy Ingots instead of the normal investigation supply.");
