    private void addCallDialogue() {
        callVariants("greeting.med_tech", "MedTec. You hurt, or need supplies?", "Medical line's open. Talk to me.", "MedTec here. What do you need?");
        callVariants("services.med_tech", "Supplies, clinical stabilization, coverage for one emergency rescue dispatch. Come see me in person and we'll get you set.", "Need treatment or rescue coverage? Stop by. We'll get you squared away.", "I can sort medical supplies and stabilization. And get your rescue coverage arranged before you walk into trouble.");
        callVariants("advice.med_tech", "Keep supplies close and get your coverage sorted before things go bad. Responders still have to reach you.", "Go down with coverage, choose Call MedTec. Respawn, and the rescue's abandoned. Remember that.", "Coverage buys you a chance, not a second life. Stay out of terrain responders can't reach.");
        callVariants("incoming.money.med_tech", "We're restocking medical supplies. Could you chip in €$%s? It's a favor, not a coverage payment.", "Short on field supplies. Can you spare €$%s? No pressure.", "Rough shift left us dry on supplies. Could you help with €$%s? Your coverage is separate.");
        callVariants("greeting.world_med_tech", "MedTec field team. Something go wrong with the patient?", "MedTec. Is the patient still alive?", "Field channel. Talk.");
        callVariants("services.world_med_tech", "One job out here: the patient. Nothing's for sale.", "No shop out here. Save the patient and we settle up.", "Field team only. Bring the beacon back and you get paid.");
        callVariants("advice.world_med_tech", "Revive them with the injector first, then use the beacon right beside them. Lose either one and the patient's gone.", "Don't drop the injector or the beacon. We can't replace them out here.", "Beacon logs wherever you stand, so stand next to the patient. I'll check. I don't take kindly to liars.");
        callVariants("quest.help.locate", "Find the patient against a wall in the marked area. Hit them with the injector, log your position next to them with the beacon, then bring the beacon to me.", "Search the marked area. Revive the patient with the injector, use the beacon right beside them, and bring it back to me in person.", "Patient first, beacon right beside them, then back to me. Log a false position and you'll answer for it. Lose an item and the contract's dead.");
        callVariants("greeting.maxtec", "MaxTec patrol. Go ahead.", "MaxTec. What do you need?", "Patrol channel's open. Keep it short.");
        callVariants("services.maxtec", "I handle threats inside the city. Medical and supplies, take that elsewhere.", "City protection's my assignment. I don't take private gigs.", "I can answer questions while the district's quiet. Hostiles come first.");
        callVariants("advice.maxtec", "Give patrols room and stay clear of creepers.", "See a threat, keep your distance. We handle what we can reach.", "Stay alert, protect the locals, and keep your hands off the officers.");
        callVariants("incoming.money.maxtec", "Could use €$%s toward replacement equipment. Can you help?", "Restocking after a rough patrol. Could you spare €$%s?", "Could you put €$%s toward some replacement kit?");
        addIncomingCallDialogue();
        String prefix = "screen.cyberneticenhancements.call.";
        add(prefix + "choice.contracts", "Any contracts available?");
        add(prefix + "choice.active_contract", "About my current contract...");
        add(prefix + "choice.questions", "Can I ask you something?");
        add(prefix + "choice.small_talk", "How are things on your end?");
        add(prefix + "choice.services", "What can you help me with?");
        add(prefix + "choice.offer", "Tell me about %s.");
        add(prefix + "choice.contract", "About %s...");
        add(prefix + "quest.which", "You've got a few jobs with me. Which one you mean?");
        add(prefix + "choice.more_contracts", "What other contracts do you have?");
        add(prefix + "choice.other_contracts", "Let me hear the other contracts.");
        add(prefix + "choice.accept_contract", "I'll take that contract.");
        add(prefix + "choice.quest_status", "How is my contract progressing?");
        add(prefix + "choice.quest_help", "What exactly do I need to do?");
        add(prefix + "choice.abandon_contract", "I want to drop this contract.");
        add(prefix + "choice.confirm_abandon", "Yes, I'm dropping it.");
        add(prefix + "choice.keep_contract", "Never mind, I'll keep it.");
        add(prefix + "quest.abandon_confirm", "You wanna walk away from %s? You won't get paid, and I'll trust you less for it. Sure?");
        add(prefix + "choice.quest_location", "Where do I need to go?");
        add(prefix + "choice.report_contract", "The job is done. Send the payment.");
        add(prefix + "quest.briefing", "%s. %s Pays %s. Interested?");
        add(prefix + "quest.accepted", "It's yours: %s. %s. Ask if you need the details again.");
        add(prefix + "quest.accepted_chat", "Contract accepted: %s. Contact: %s.");
        add(prefix + "quest.paid_chat", "Contract completed: %s. Reward: %s. Any item rewards will be delivered to your Dropoff Point.");
        add(prefix + "quest.paid_direct_chat", "Contract completed: %s. Reward: %s.");
        add(prefix + "quest.offer_gone", "That offer's gone. Let me see what I've got now.");
        add(prefix + "quest.max_active", "You've already got a gig from this contact. Finish or drop it before you take another.");
        add(prefix + "quest.no_active", "You're not working a gig for me right now. Want to hear what's available?");
        add(prefix + "quest.status", "%s. %s. %s");
        add(prefix + "quest.in_progress", "Still open. Ask if you need the instructions or the destination again.");
        add(prefix + "quest.ready_remote", "Objective's done. Turn it in here or through the archive. I'll credit your account now and send any item rewards to your Dropoff Point. Meet me in person if you want the items right away.");
        add(prefix + "quest.ready_in_person", "Bring the items to me in person. I need them in my hands before I can pay. Your compass marks where I am.");
        add(prefix + "quest.ready_report", "Come and tell me in person where you found them. I need to hear it from you before I pay. Your compass marks where I am.");
        add(prefix + "quest.report_unavailable", "Can't close this one yet. Make sure the objective's done and you've still got whatever I asked for.");
        add(prefix + "quest.location", "Site's at %s, %s, %s in %s. %s");
        add(prefix + "quest.location_navigation", "Follow the gold quest marker on your compass. Its height indicator helps with underground and underwater sites.");
        add(prefix + "quest.location_investigation", "The marker shows the survey area until you've got three bearings, then it points to the source cache. Crouch with empty hands, hold still for three seconds to scan, and move sideways between readings. Breach the cache once you've located it.");
        add(prefix + "quest.no_site", "No fixed site for this one. Gather %s %s and bring them to me.");
        callVariants("back", "Anything else?", "Alright. What else?", "Still here. What do you need?");
        callVariants("greeting.fixer", "Yeah, you got me. What do you need?", "Got a minute. Talk to me.", "Good timing. What's the play?");
        callVariants("greeting.ripperdoc", "Clinic. Everything alright?", "Between patients. What can I do, kid?", "Go ahead. What do you need?");
        callVariants("greeting.techie", "Hey. Putting the tools down. What's up?", "Caught me in the workshop. Go ahead.", "Yeah, I'm listening. Need a gig or directions?");
        callVariants("greeting.netrunner", "Line's clear. What's up?", "I'm here. Need a job, or a hand with one?", "Hold on... alright, talk to me.");
        callVariants("greeting.merc", "Yeah? Make it quick, I'm on watch.", "I'm clear. What do you need?", "You got me. What's going down?");
        callVariants("greeting.night_sleepy", "You woke me up. This better be worth it.", "You know what time it is? Fine, I'm listening.", "I was asleep. Give me a sec. What do you need?");
        callVariants("greeting.night_awake", "Still up too, huh? Alright, what's the gig?", "Quiet night so far. What do you need?", "Wasn't sleeping anyway. Go ahead.");
        callVariants("greeting.rain", "Hold on, getting out of the rain. Go ahead.", "It's pouring out here. Hope you've got something good.", "That noise is the rain, on my end. What do you need?");
        callVariants("greeting.storm", "Thunder cuts me off, call back. What's up?", "Great timing. I'm looking for cover from this storm.", "Storm's right on top of me. Make it quick.");
        callVariants("greeting.trusted", "Hey, good to hear from you. What do you need?", "For you? I've got time. Go ahead.", "There you are. How can I help, choom?");
        callVariants("greeting.annoyed", "I'm answering, but don't push it. What do you want?", "Keep it short. We're not on the best terms.", "Alright, one minute. Make it count.");
        callVariants("meeting.normal", "Alright, I'll come to you. Talk when I get there.", "Stay put. I'll meet you in person.", "Sure. Ending the call and heading over.");
        callVariants("meeting.rain", "Fine, but I'll be soaked by the time I get there. Find us some cover.", "In this rain? You owe me a dry spot. On my way.", "I'll meet you. Get under a roof. Not discussing this in the rain.");
        callVariants("meeting.storm", "With that storm out there? Fine, but find cover before I show up.", "Picking a hell of a time to meet. Stay somewhere sheltered.", "I'll come, but let's stay out of the lightning. See you in a bit.");
        callVariants("meeting.night", "Dragging me out this late? Fine. Stay put.", "Alright, a late-night meet it is. Coming over.", "I'll come to you. Make it worth losing sleep over.");
        callVariants("cannot_meet", "Can't get to you right now. We gotta be in the same dimension, and I gotta be free.", "Not now. Keep talking, or try again when I'm free and we're in the same dimension.", "Can't make that meet from here. Try again when we share a dimension and I'm free.");
        callVariants("location", "I'm at %s. Follow the blue outline, I've marked myself for you.", "Sending my position: %s. Look for the blue outline.", "You'll find me at %s. Got a blue locator outline on for you.");
        callVariants("questions", "Sure. What d'you wanna know?", "Go ahead, I'm listening.", "Ask away. I'll tell you what I can.");
        callVariants("contracts", "Got a few gigs. Pick one and I'll give you the details.", "There's work. Which gig you wanna hear about?", "Let me check the board. These are the gigs I've got for you.");
        callVariants("no_contracts", "Board's empty right now. Check back tomorrow.", "No gigs at the moment. Try me another day.", "Fresh out of offers. I'll look again tomorrow.");
        callVariants("quest.abandoned", "Fine. %s is off your slate, but don't make a habit of it.", "Your call. I'll strike %s from the board. I won't forget it.", "%s is canceled. Next time, think before you sign on.");
        callVariants("quest.paid", "Confirmed. Payment's headed your way: %s.", "Nice work. Your payment's on the way: %s.", "That's the gig closed. You've earned %s.");
        callVariants("small_talk.normal", "Keeping busy. There's always another job waiting.", "Quiet for now. I'll take it while it lasts.", "Nothing I can't handle. How's your end?");
        callVariants("small_talk.night", "Trying to get through the night without another problem landing on my doorstep.", "It's late. Hoping it stays quiet for once.", "Ask me after I've slept. For now, I'm managing.");
        callVariants("small_talk.rain", "Wet. Mostly wet. Can't wait to get indoors.", "This rain's making everything take twice as long.", "I'd be better off somewhere dry. Otherwise, can't complain.");
        callVariants("small_talk.annoyed", "Let's keep it to business right now.", "Let's not pretend everything's fine. What do you need?", "Not in the mood for small talk. We can still talk work.");
        callVariants("services.fixer", "Supplies, strain buffers, neural resets, relic-cache leads. Come see me for stock and services.", "I sell supplies, help with strain, and point you toward a relic cache. All in person, choom.", "Need supplies, a strain buffer or a cache lead? Find me in person and we'll sort it.");
        callVariants("services.ripperdoc", "Clinic care, detox, medical supplies, basic implants. Come in for treatment. Implant repairs need a Repair Station.", "Treatment, detox, medical stock. Can't look you over through a phone, kid.", "I can help with injuries and strain, sell medical supplies. For busted chrome, Repair Station.");
        callVariants("services.techie", "Workshop parts, mining calibration, hazard prep, gigs. Take a job on this call. Parts and services need a visit.", "I can hand out gigs over the line. Come to the workshop for components, mining support and hazard prep.", "Jobs over the phone, parts and calibration in person. Ask about gigs if you want work.");
        callVariants("services.netrunner", "Gear, recon support, stealth prep, gigs and cache leads. Gigs I can arrange on this call.", "I can brief you on jobs remotely. Gear, recon and cache leads need an in-person visit.", "Need a gig, or help making sense of one? Here, fine. Come see me for gear and services.");
        callVariants("services.merc", "Combat supplies, recovery, prep, gigs. We can talk work here. Supplies and services need a visit.", "I can offer work and walk you through it remotely. Come see me for combat kit and prep.", "Jobs by phone, gear in person. Recovery and combat prep too, when you visit.");
        callVariants("advice.fixer", "Watch your strain. A buffer buys time, it doesn't make heavy chrome harmless.", "Hunting a relic cache, ask me in person. I can mark a known one on your compass.", "Don't spend your last eddie before a long trip. Keep enough for supplies or treatment.");
        callVariants("advice.ripperdoc", "If your cyberstrain keeps climbing, stop and deal with it before you take on more trouble, kid.", "Check implant integrity before a fight. Treatment and cyberware repair, two different jobs.", "Damaged implant goes to a Repair Station. Medical consumables won't fix hardware.");
        callVariants("advice.techie", "Read your schematics before you try fabricating hardware. Knowing the recipe matters.", "Check your upgrade materials before you commit. Some steps need more than basic parts.", "Recycling, repairing, upgrading. Separate stations. Pick the one that actually does the job.");
        callVariants("advice.netrunner", "At a relic cache, plan your route through the matrix before you burn the buffer.", "Don't expect to clear every cache reward. Pick the sequences worth chasing.", "Stuck on a gig? Ask me for the objective or the destination. Guessing wastes time.");
        callVariants("advice.merc", "Check implant integrity and supplies before you pick a fight.", "On a marked hunt, head for the gig site. Your compass marks it.", "Job goes bad, take a minute and recover. Starting the next fight hurt rarely helps.");
        callVariants("quest.help.delivery", "Take the package to the marked Iron Quest Crate and drop it inside. Wait for confirmation. Don't bring it back to me.", "Follow the delivery marker on your compass, open the Iron Quest Crate and deposit the package. Could be underwater or underground.", "Package goes in the marked Iron Quest Crate. Once the delivery registers, call back for payment.");
        callVariants("quest.help.extraction", "Follow the extraction marker and pull the shard from the Iron Quest Crate. Bring it back to me in person for payment.", "Grab the exfil shard from the marked Iron Quest Crate, then hand it to me in person. Call or archive can't carry a shard.", "Reach the marked Iron Quest Crate and take the shard. You gotta bring it to me in person to finish the gig and get paid.");
        callVariants("quest.help.investigation", "Head to the survey area on your compass. Crouch with both hands empty and hold still for three seconds. Take three bearings, moving 32 to 48 blocks sideways each time, then breach the source cache.", "Don't walk the same line for every reading. Spread your three scans around the survey area so the bearings cross. The compass marks the source after triangulation. Breach its cache to finish.", "You need three separated readings at different angles. Crouch, empty both hands and hold still to scan within 160 blocks of the survey marker. Once the source is located, breach the cache and get the data.");
        callVariants("quest.help.breach", "Follow the breach marker to the cache. One attempt, committed with your first pick. Run out of time, fill the buffer without clearing every sequence, or close the breach halfway, and the job's blown and it costs you trust.", "Find the marked cache and plan before your first pick. After that, you finish the puzzle in one go. Fail and you lose trust. Win and you call me for payment.", "Use your compass to find the cache for this gig. It disappears after you succeed. No retry after your first pick. Fail or walk out of the breach, and the contract fails and it costs you trust.");
        callVariants("quest.help.elimination", "Go to the marked hunt site and take down %s %s there. Kills anywhere else don't count.", "Gig needs %s %s dropped at the marked site. Use the hunt marker on your compass and watch your progress.", "Follow the hunt marker on your compass and put down %s %s at the marked site. Once it's confirmed, report in on this call.");
        callVariants("quest.help.recovery", "Gather %s %s and bring them to me in person. I need the actual materials before I pay.", "I need %s %s. Get them however you like, then meet me and hand them over in person.", "Bring me %s %s in person. No marked pickup. You're sourcing it yourself.");
        callVariants("quest.help.cyberpsycho", "Compass marks an approximate sighting. Search within 48 blocks, put the cyberpsycho down, then pick up their named dossier shard. Hand it to me in person for payment.", "Expect a heavily chromed opponent. Red name means aggressive. Dodge launcher shots and blade lunges. Kill the target and bring their information shard to me in person.", "Find the cyberpsycho in the marked area. Killing them is only half the job: grab the dossier off the body, then bring it to me in person. These gigs pay the best we've got, and damaged cyberware sometimes survives the fight.");
    }

    private void addIncomingCallDialogue() {
        add("wiki.cyberneticenhancements.npc.general.contacts_archive.6", "Contacts can call you. Answer with Alt+1 or decline with Alt+2; unanswered calls stop after 30 seconds. Connected NPCs hang up after 10 seconds without a conversation reply, with no trust or quest penalty. An issuer may check on a contract after two hours of online play time. Trusted contacts may occasionally ask for a small contribution, which you must explicitly approve; declining a money request costs nothing. Automatic calls have a 30-minute overall cooldown and a two-hour repeat cooldown per contract, money request or urgent issuer; these survive reconnects and respawns. Hidden contacts do not make routine calls; missing quest evidence can still trigger an angry call.");
        add("wiki.cyberneticenhancements.npc.general.contacts_archive.7", "Contract issuers can occasionally call with a specific urgent job when you have no active contract from them. Answer to review the objective and boosted payout. Accepting through that offer adds 25% money and one extra trust to its completion rewards. Explicitly refusing the job costs one trust and withdraws that offer; missing or declining the ringing call costs nothing. Urgent contracts are labeled in the quest log and keep their bonus through saving and reconnects. Urgency does not add a completion deadline.");
        String prefix = "screen.cyberneticenhancements.call.";
        add(prefix + "incoming.title", "Incoming: %s");
        add(prefix + "incoming.ringing", "Incoming call...");
        add(prefix + "incoming.notice", "Incoming call from %s. Answer or decline using the call HUD.");
        add(prefix + "incoming.missed", "Missed call. The contact stopped ringing.");
        add(prefix + "incoming.quest_changed", "I was calling about that contract, but looks like things changed. Anything else you need?");
        add(prefix + "incoming.money_insufficient", "Looks like your account's light. Forget it, don't worry about it.");
        add(prefix + "incoming.money_sent_chat", "Sent €$%s to %s.");
        add(prefix + "choice.answer", "Answer call");
        add(prefix + "choice.decline", "Decline call");
        add(prefix + "choice.send_money", "Send €$%s.");
        add(prefix + "choice.decline_money", "Sorry, I can't spare the money.");
        add(prefix + "choice.change_subject", "Can we talk about something else?");
        add(prefix + "choice.working_on_it", "I'm still working on it.");
        add(prefix + "choice.accept_urgent", "I'll take this job. (+25% pay, +1 trust)");
        add(prefix + "choice.decline_urgent", "I can't take it. (-1 trust)");
        add(prefix + "incoming.urgent_accepted", "%s is yours. %s Pays %s on completion, urgency bonus included.");
        add(prefix + "incoming.urgent_deadline", " You have %s minutes of online play to finish the objective.");
        add(prefix + "incoming.urgent_declined_chat", "Declined %s's urgent contract. Trust -1.");
        callVariants("incoming.urgent.techie", "Need this handled fast: %s. %s Pays %s, urgency bonus included. You in?", "Got a rush job for you: %s. %s I'll pay %s when it's done. You in?", "Calling about %s. Need a hand with this one. %s Pays %s, bonus included.");
        callVariants("incoming.urgent.netrunner", "Urgent gig just came in: %s. %s Pays %s, extra for taking it now. Can I count on you?", "Need someone for %s. %s I'll pay %s when it's done. That's the boosted rate.", "Priority work: %s. %s Payout's %s, urgency bonus included. Interested?");
        callVariants("incoming.urgent.merc", "Need a hand with %s. %s Pays %s, extra for the rush. You in?", "Got an urgent job: %s. %s I'll pay %s when it's done. You free?", "Calling you about %s. %s Pays %s, bonus included. Can I put you on it?");
        callVariants("incoming.urgent_declined", "Alright. I'll find someone else. I was counting on you for this one.", "Understood. I needed help on this, so that's a shame. I'll make other arrangements.", "Fine. I'll ask someone else. Thought I could rely on you here.");
        callVariants("incoming.checkin", "Hey, got a minute? Thought I'd check in. What can I do?", "It's me. Caught you while we both had a moment.", "Hey. Just checking you're still out there. Need anything?");
        callVariants("incoming.overdue", "Calling about %s. You took that job hours ago. What's holding you up?", "Any news on %s? Been a while since you signed on. You need the instructions again?", "We need to talk about %s. That gig's been open for hours. Still working on it?");
        callVariants("incoming.acknowledged", "Alright. Keep me posted. Ask if you need the details again.", "Good. Let me know when you've got something to report.", "Understood. I'm here if you need the destination or the instructions.");
        callVariants("incoming.money.fixer", "Quick favor. Covering a few expenses today. Can you spare €$%s? It's help, not a loan.", "Bit short on funds for a deal. Could you send €$%s? No pressure if you can't.", "Could use €$%s toward some expenses. You don't owe me anything. I'm asking as a contact.");
        callVariants("incoming.money.ripperdoc", "Clinic's running low on supplies, kid. Could you chip in €$%s for the next order?", "Stocking up for patients. Could you spare €$%s toward the medical supplies?", "Small favor: €$%s would cover some clinic supplies. Entirely up to you.");
        callVariants("incoming.money.techie", "Parts order came up short. Could you spare €$%s to cover it?", "Need a little help keeping the workshop stocked. Could you chip in €$%s?", "Replacing some worn tools. Would you pitch in €$%s?");
        callVariants("incoming.money.netrunner", "Fried a piece of gear. Could use €$%s toward a replacement. Can you help?", "Short on replacement hardware. Could you spare €$%s? No worries if not.", "Got hit with an unexpected equipment bill. Would you chip in €$%s?");
        callVariants("incoming.money.merc", "Restocking after a rough job. Could you spare €$%s for supplies?", "Could use €$%s toward some replacement kit. Can you help a contact out?", "Need to patch up my gear. Would you pitch in €$%s?");
        callVariants("incoming.money_declined", "No problem. Had to ask. We can still talk business.", "Understood. Keep what you need. Anything else?", "Fair enough. Don't put yourself short on my account.");
        callVariants("incoming.money_thanks", "Got it. Thanks, that helps.", "Received. You're doing me a favor here. Thanks.", "It came through. Thanks for helping out.");
        String command = "command.cyberneticenhancements.calls.";
        add(command + "not_npc", "Choose a Cybernetic Enhancements NPC.");
        add(command + "unavailable", "Call could not start. Check for an occupied line, an open container, an unavailable NPC, a missing overdue contract, or no eligible urgent offer from that contact.");
        add(command + "forced", "%s is calling %s (%s).");
        add(command + "started", "Started an eligible incoming call for %s.");
        add(command + "no_call", "No incoming call started for %s. Eligibility, cooldowns and normal urgent-offer / money-request randomness still apply.");
        add(command + "reset", "Reset incoming-call cooldowns for %s.");
        add(command + "status", "%s: %s minutes played; incoming-call cooldown: %s minutes; call active: %s.");
        add(command + "no_quest", "That player has no active contract from this NPC.");
        add(command + "aged", "Set the age of %s's active contract to %s minutes of play time.");
    }

